import{_ as e,o as a,c as r,a5 as o}from"./chunks/framework.CYLkiqTo.js";const p=JSON.parse('{"title":"长期记忆","description":"","frontmatter":{"title":"长期记忆","chapter":"3.3","order":3,"summary":"对比本地文件、向量库与 mem0 三类持久化方案，并按情景/语义/程序性记忆分类组织跨会话知识。"},"headers":[],"relativePath":"03-context-memory/long-term-memory.md","filePath":"03-context-memory/long-term-memory.md","lastUpdated":1788375627000}'),n={name:"03-context-memory/long-term-memory.md"};function d(l,t,i,m,s,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="长期记忆" tabindex="-1">长期记忆 <a class="header-anchor" href="#长期记忆" aria-label="Permalink to &quot;长期记忆&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>长期记忆解决跨会话、跨运行的知识留存问题，使 Agent 在多日任务中积累经验而非每次从零开始，是 RAG 与 Session State 之外的持久层。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p><strong>存储选型对比</strong>：</p><table tabindex="0"><thead><tr><th>方案</th><th>写入成本</th><th>检索方式</th><th>适合场景</th><th>局限</th></tr></thead><tbody><tr><td>本地文件（append-only log / 结构化 md）</td><td>极低</td><td>全文/前缀扫描</td><td>小规模、可审计、单人</td><td>规模大后检索慢</td></tr><tr><td>向量库（pgvector / Qdrant）</td><td>中</td><td>语义近邻</td><td>大规模非结构化知识</td><td>需维护 embedding</td></tr><tr><td>mem0</td><td>中高</td><td>自动抽取+语义</td><td>多 agent 共享、经验沉淀</td><td>黑盒、外部依赖</td></tr></tbody></table><p><strong>三类记忆划分</strong>：</p><ul><li><strong>情景记忆（episodic）</strong>：具体发生过的事（“上次部署失败了因为端口冲突”）→ 本地 log 或向量库。</li><li><strong>语义记忆（semantic）</strong>：提炼的事实与偏好（“用户偏好 TypeScript”）→ 结构化 md / mem0。</li><li><strong>程序性记忆（procedural）</strong>：可复用的操作套路 → Skill 或工具固化，而非纯文本。</li></ul><p>最小实现：用 append-only <code>memory.md</code>，每次运行结束追加一条结构化记录；检索时按标签 grep，规模上来再迁向量库。</p><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>没有长期记忆，Agent 每次会话都是“失忆患者”，重复踩坑、无法个性化。但过早引入重方案（向量库/mem0）会增加运维面——按数据量增长切换即可。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>把所有东西塞向量库，却没区分三类记忆，导致检索噪声高。</li><li>本地文件不 append-only，被后续运行覆盖而丢失历史。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li>mem0：显式区分 episodic/semantic/procedural，提供统一 API（<a href="https://docs.mem0.ai/" target="_blank" rel="noreferrer">docs</a>）。</li><li>LangChain：<code>VectorStore</code> + <code>Memory</code> 抽象持久化语义记忆（<a href="https://python.langchain.com/docs/integrations/providers/" target="_blank" rel="noreferrer">docs</a>）。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/03-context-memory/rag">RAG 检索增强</a></li><li><a href="/fk-ai-agent/03-context-memory/session-state">会话状态与恢复</a></li><li><a href="/fk-ai-agent/03-context-memory/context-engineering">上下文工程</a></li><li><a href="/fk-ai-agent/02-capability-extension/skill-management">Skill 管理</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',19)])])}const g=e(n,[["render",d]]);export{p as __pageData,g as default};
